 * Policy implementations: token buckets and sliding windows.
 *
 * Both expose a common per-key interface used by the simulator:
 *   advance(key, tick) - move the key's state forward to `tick`
 *   allowed(key)        - would a request at the current state be allowed?
 *   record(key, tick)   - actually consume/record the request
 */

export class TokenBucket {
  constructor(capacity, refill, per) {
    this.refill = refill
    this.per = per
    // Track levels in units of 1/per of a token so that "refill tokens
    // every per ticks" is always an exact integer number of units per
    // tick, with no fractional rounding required anywhere.
    this.capacityUnits = capacity * per
    this.levels = new Map()
    this.lastTick = new Map()
  }

  advance(key, tick) {
    if (!this.levels.has(key)) {
      this.levels.set(key, this.capacityUnits)
      this.lastTick.set(key, tick)
      return
    }
    const last = this.lastTick.get(key)
    const elapsed = tick - last
    let level = this.levels.get(key) + this.refill * elapsed
    if (level > this.capacityUnits) level = this.capacityUnits
    this.levels.set(key, level)
    this.lastTick.set(key, tick)
  }

  allowed(key) {
    return this.levels.get(key) >= this.per
  }

  record(key) {
    this.levels.set(key, this.levels.get(key) - this.per)
  }
}

export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.records = new Map()
  }

  advance(key, tick) {
    let arr = this.records.get(key)
    if (!arr) {
      arr = []
      this.records.set(key, arr)
    }
    const threshold = tick - this.span
    let i = 0
    while (i < arr.length && arr[i] <= threshold) i++
    if (i > 0) arr.splice(0, i)
  }

  allowed(key) {
    return BigInt(this.records.get(key).length) < this.limit
  }

  record(key, tick) {
    this.records.get(key).push(tick)
  }
}
"}

