 * Parses a limiter file and replays its events against the declared
 * policies, producing either a per-event replay log or a per-key summary.
 */

import { TokenBucket, SlidingWindow } from './policies.js'

const NAME_RE = /^[A-Za-z0-9_.\/:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

export class LineError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

function fail(line, reason) {
  throw new LineError(line, reason)
}

function parseIntField(line, token, fieldName, min) {
  if (!INT_RE.test(token) || BigInt(token) < min) {
    fail(line, `${fieldName} must be an integer of at least ${min}`)
  }
  return BigInt(token)
}

function checkName(line, name, kind) {
  if (!NAME_RE.test(name)) fail(line, `${kind} ${name}`)
}

export function run(mode, text) {
  let lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routes = []
  const routePrefixes = new Map()
  let eventSeen = false
  let lastTick = null

  const perKey = new Map()
  const keyOrder = []
  const replayLines = []
  let totalAllowed = 0
  let totalDenied = 0

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]

    if (word === 'bucket' || word === 'window' || word === 'route') {
      if (eventSeen) fail(lineNo, 'declarations must come before the first event')

      if (word === 'bucket') {
        if (tokens.length !== 5) fail(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
        const name = tokens[1]
        checkName(lineNo, name, 'invalid policy name')
        const capacity = parseIntField(lineNo, tokens[2], 'capacity', 1n)
        const refill = parseIntField(lineNo, tokens[3], 'refill', 0n)
        const per = parseIntField(lineNo, tokens[4], 'per', 1n)
        if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
        policies.set(name, new TokenBucket(capacity, refill, per))
      } else if (word === 'window') {
        if (tokens.length !== 4) fail(lineNo, 'expected window <name> <limit> <span>')
        const name = tokens[1]
        checkName(lineNo, name, 'invalid policy name')
        const limit = parseIntField(lineNo, tokens[2], 'limit', 0n)
        const span = parseIntField(lineNo, tokens[3], 'span', 1n)
        if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
        policies.set(name, new SlidingWindow(limit, span))
      } else {
        if (tokens.length < 2) fail(lineNo, 'expected route <prefix> <policy>...')
        const prefix = tokens[1]
        checkName(lineNo, prefix, 'invalid route prefix')
        if (routePrefixes.has(prefix)) fail(lineNo, `prefix ${prefix} is routed twice`)
        const policyNames = tokens.slice(2)
        for (const pn of policyNames) {
          if (!policies.has(pn)) fail(lineNo, `unknown policy ${pn}`)
        }
        const route = { prefix, policies: policyNames }
        routePrefixes.set(prefix, route)
        routes.push(route)
      }
      continue
    }

    if (word === 'event') {
      eventSeen = true
      if (tokens.length !== 3) fail(lineNo, 'expected event <tick> <key>')
      const tick = parseIntField(lineNo, tokens[1], 'tick', 0n)
      const key = tokens[2]
      checkName(lineNo, key, 'invalid key')
      if (lastTick !== null && tick < lastTick) fail(lineNo, `tick ${tick} is before tick ${lastTick}`)
      lastTick = tick

      let route = null
      for (const r of routes) {
        if (key.startsWith(r.prefix)) {
          if (route === null || r.prefix.length > route.prefix.length) route = r
        }
      }

      let verdict = 'allow'
      let denyPolicy = null

      if (route) {
        const insts = route.policies.map((n) => policies.get(n))
        for (const inst of insts) inst.advance(key, tick)
        let denyIndex = -1
        for (let j = 0; j < insts.length; j++) {
          if (!insts[j].allowed(key)) {
            denyIndex = j
            break
          }
        }
        if (denyIndex >= 0) {
          verdict = 'deny'
          denyPolicy = route.policies[denyIndex]
        } else {
          for (const inst of insts) inst.record(key, tick)
        }
      }

      if (!perKey.has(key)) {
        perKey.set(key, { allowed: 0, denied: 0 })
        keyOrder.push(key)
      }
      const stat = perKey.get(key)
      if (verdict === 'allow') {
        stat.allowed++
        totalAllowed++
      } else {
        stat.denied++
        totalDenied++
      }

      if (mode === 'replay') {
        if (verdict === 'allow') {
          replayLines.push(`${tick} ${key} allow`)
        } else {
          replayLines.push(`${tick} ${key} deny ${denyPolicy}`)
        }
      }
      continue
    }

    fail(lineNo, `unknown directive ${word}`)
  }

  if (mode === 'replay') {
    return replayLines.length > 0 ? replayLines.join('\n') + '\n' : ''
  }

  const summaryLines = []
  const sortedKeys = [...perKey.keys()].sort()
  for (const key of sortedKeys) {
    const stat = perKey.get(key)
    summaryLines.push(`${key} allowed=${stat.allowed} denied=${stat.denied}`)
  }
  summaryLines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
  return summaryLines.join('\n') + '\n'
}
"}

